  {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is edge case data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's the deliberate capture of rare, high-impact scenarios a robot meets in deployment but seldom sees in training, such as unusual objects, lighting, human behavior, sensor faults, and near-failures. It's driven by real failure logs rather than random recording hours."
        }
      },
      {
        "@type": "Question",
        "name": "How do you find edge cases we don't know about yet?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "We start with your incident logs, interventions, and disengagements, then run structured field sessions designed to stress the system across our five-category taxonomy. New failures found there are scored and added to the Tail Ledger."
        }
      },
      {
        "@type": "Question",
        "name": "Should we use simulation or real-world data for edge cases?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Both, for different jobs. Simulation is useful for scenarios too dangerous or rare to stage. Real-world capture is needed to confirm the failure and validate the fix, because sensor behavior in glare, fog, or clutter is hard to simulate faithfully."
        }
      },
      {
        "@type": "Question",
        "name": "How many examples of an edge case do we need?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Enough variations for the model to learn the pattern rather than one instance, plus a held-out set for evaluation. We size each scenario during the pilot by checking whether failure rates drop on the held-out variations."
        }
      },
      {
        "@type": "Question",
        "name": "How do you collect dangerous edge cases safely?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Human-interaction and collision scenarios start with mannequins, reduced speeds, and emergency stops under a reviewed safety protocol. Some cases are simulated first and verified with small, controlled real captures."
        }
      },
      {
        "@type": "Question",
        "name": "How do edge cases connect to validation and testing?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Held-out edge case sets become regression suites. Every model version is tested against them, so you can show a failure was fixed and stays fixed across releases."
        }
      }
    ]
  }
